import assert from 'node:assert/strict';
globalThis.sampleRate=48000;globalThis.AudioWorkletProcessor=class{constructor(){this.port={onmessage:null,postMessage(){}};}};let Processor;globalThis.registerProcessor=(_,p)=>Processor=p;await import('./cortex-worklet.js');
const p=new Processor();p.port.onmessage({data:{type:'params',value:{active:true,output:1,voiceLimit:16,binaural:true,variation:0,octaves:0,reverb:1,reverbSize:1,droneEnabled:true}}});p.port.onmessage({data:{type:'state',voices:Float32Array.from({length:48},(_,i)=>i%3===0?1:0)}});let peak=0;for(let b=0;b<1800;b++){if(b%40===0)for(let g=0;g<16;g++)p.port.onmessage({data:{type:'pulse',event:{group:g,strength:1}}});const output=[new Float32Array(128),new Float32Array(128)];p.process([],[output]);for(const channel of output)for(const x of channel){assert.ok(Number.isFinite(x)&&Math.abs(x)<=1);peak=Math.max(peak,Math.abs(x));}}
assert.ok(peak>.01);assert.ok(p.activeVoiceCount()<=16);p.port.onmessage({data:{type:'params',value:{active:false}}});for(let b=0;b<200;b++)p.process([],[[new Float32Array(128),new Float32Array(128)]]);const stopped=[new Float32Array(128),new Float32Array(128)];p.process([],[stopped]);assert.ok(stopped.every(c=>c.every(x=>x===0)));assert.equal(p.reverbNetwork.idle,true);
